/**
 * S3 Node - Version 1
 * Discriminator: resource=file, operation=delete
 */


interface Credentials {
  s3: CredentialReference;
}

/** Delete a bucket */
export type S3V1FileDeleteParams = {
  resource: 'file';
  operation: 'delete';
/**
 * Bucket Name
 */
    bucketName: string | Expression<string>;
/**
 * File Key
 */
    fileKey: string | Expression<string>;
/**
 * Options
 * @default {}
 */
    options?: {
    /** Version ID
     */
    versionId?: string | Expression<string>;
  };
};

export type S3V1FileDeleteOutput = {
  success?: boolean;
};

export type S3V1FileDeleteNode = {
  type: 'n8n-nodes-base.s3';
  version: 1;
  config: NodeConfig<S3V1FileDeleteParams> & { credentials?: Credentials };
  output?: Items<S3V1FileDeleteOutput>;
};